"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7969],{79443:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Builds a queue. Every field except `name` and `size` has a default.","params":[{"name":"config","desc":"","lua_type":"MatchmakerConfig"}],"returns":[{"desc":"","lua_type":"any\\n"}],"function_type":"static","errors":[{"lua_type":"\\"Muster: ...\\"","desc":"Any configuration problem, reported at your call site."}],"source":{"line":128,"path":"src/Matchmaker.luau"}},{"name":"enqueue","desc":"Queues one player.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"userId","desc":"","lua_type":"number"},{"name":"options","desc":"","lua_type":"EnqueueOptions?"}],"returns":[{"desc":"","lua_type":"any\\n"}],"function_type":"static","source":{"line":233,"path":"src/Matchmaker.luau"}},{"name":"enqueueGroup","desc":"Queues an arbitrary set of players as one indivisible ticket, without using\\nMuster\'s own party system. Use this when you already have parties or squads\\nof your own.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"userIds","desc":"","lua_type":"{ number }"},{"name":"options","desc":"","lua_type":"GroupOptions?"}],"returns":[{"desc":"","lua_type":"any\\n"}],"function_type":"static","source":{"line":261,"path":"src/Matchmaker.luau"}},{"name":"enqueueParty","desc":"Queues a Muster party. Only its leader may do this, and the party\'s\\nmembership is frozen until the ticket resolves.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"partyId","desc":"","lua_type":"string"},{"name":"requesterUserId","desc":"","lua_type":"number"},{"name":"options","desc":"","lua_type":"GroupOptions?"}],"returns":[{"desc":"","lua_type":"any\\n"}],"function_type":"static","source":{"line":292,"path":"src/Matchmaker.luau"}},{"name":"cancel","desc":"Cancels a ticket. Only its leader may do so, and only while it is still\\nqueued \u2014 a ticket already claimed for a match cannot be pulled back.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"requesterUserId","desc":"","lua_type":"number"},{"name":"ticketId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"any\\n"}],"function_type":"static","source":{"line":366,"path":"src/Matchmaker.luau"}},{"name":"cancelForUser","desc":"Cancels whatever ticket a user holds, if any. Wired to `PlayerRemoving`\\nautomatically unless `autoCancelOnLeave` is off.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"userId","desc":"","lua_type":"number"}],"returns":[{"desc":"Whether a ticket was actually cancelled.","lua_type":"Result<boolean>"}],"function_type":"static","source":{"line":377,"path":"src/Matchmaker.luau"}},{"name":"getTicket","desc":"","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"userId","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"any\\n"}],"function_type":"static","source":{"line":397,"path":"src/Matchmaker.luau"}},{"name":"getStatus","desc":"","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"ticketId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"any\\n"}],"function_type":"static","source":{"line":404,"path":"src/Matchmaker.luau"}},{"name":"getMatch","desc":"Reads a finalized match by id \u2014 useful for a player who rejoined on a new\\nserver and needs the envelope again.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"matchId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"any\\n"}],"function_type":"static","source":{"line":414,"path":"src/Matchmaker.luau"}},{"name":"acknowledge","desc":"Releases a ticket\'s players so they can queue again, and unlocks its party.\\nDone for you unless `manualAcknowledge` is set, which is what you want if\\nteleporting can fail and you need the option to re-queue.","params":[{"name":"self","desc":"","lua_type":"any"},{"name":"requesterUserId","desc":"","lua_type":"number"},{"name":"ticketId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"any\\n"}],"function_type":"static","source":{"line":425,"path":"src/Matchmaker.luau"}},{"name":"step","desc":"Runs one worker pass. The loop calls this for you; call it directly in tests\\nto advance the system a step at a time.","params":[{"name":"self","desc":"","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":435,"path":"src/Matchmaker.luau"}},{"name":"start","desc":"","params":[{"name":"self","desc":"","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":442,"path":"src/Matchmaker.luau"}},{"name":"stop","desc":"Stops the worker and hands back every lease, so another server picks the\\nwork up at once rather than waiting for a timeout. Call it from\\n`BindToClose`.","params":[{"name":"self","desc":"","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":453,"path":"src/Matchmaker.luau"}},{"name":"destroy","desc":"Stops everything and drops all signal handlers.","params":[{"name":"self","desc":"","lua_type":"any"}],"returns":[],"function_type":"static","source":{"line":462,"path":"src/Matchmaker.luau"}},{"name":"health","desc":"A snapshot for logging or a debug command: how many tickets this server has\\nqueued, how many lanes it is working, whether broadcasts look healthy, and\\nper-structure request health.","params":[{"name":"self","desc":"","lua_type":"any"}],"returns":[{"desc":"","lua_type":"any\\n"}],"function_type":"static","source":{"line":481,"path":"src/Matchmaker.luau"}}],"properties":[],"types":[],"name":"Matchmaker","desc":"A queue. Construct one per game mode, enqueue players, and listen for\\nmatches.\\n\\n```lua\\nlocal Muster = require(ReplicatedStorage.Packages.Muster)\\n\\nlocal duels = Muster.new({ name = \\"duels\\", size = 2 })\\n\\nduels.matched:connect(function(match)\\n\\tfor _, member in match.members do\\n\\t\\tprint(member.userId, \\"->\\", match.matchId)\\n\\tend\\nend)\\n\\nduels:enqueue(player.UserId)\\n```\\n\\nThat is the whole setup. The worker starts itself, subscribes for\\ncross-server delivery, cleans up when players leave, and matches on its\\nfirst scan.\\n\\n### The finalize hook\\n\\nMuster stops at the match envelope: it never teleports and never reserves\\nservers, because every game wants that done differently. Instead, `finalize`\\nruns once per match on whichever server formed it, and whatever it returns\\nis attached to the envelope as `match.data` and delivered to everyone.\\n\\n```lua\\nlocal ranked = Muster.new({\\n\\tname = \\"ranked\\",\\n\\tsize = { min = 4, target = 8, max = 8 },\\n\\trating = { window = 150, relax = 25, default = 1000 },\\n\\n\\tfinalize = function(match)\\n\\t\\treturn {\\n\\t\\t\\taccessCode = TeleportService:ReserveServerAsync(ARENA_PLACE),\\n\\t\\t\\tmap = pickMap(match.size),\\n\\t\\t}\\n\\tend,\\n})\\n\\nranked.matched:connect(function(match)\\n\\tlocal present = {}\\n\\tfor _, member in match.members do\\n\\t\\tlocal player = Players:GetPlayerByUserId(member.userId)\\n\\t\\tif player then table.insert(present, player) end\\n\\tend\\n\\tif #present == 0 then return end\\n\\tTeleportService:TeleportToPrivateServer(ARENA_PLACE, match.data.accessCode, present)\\nend)\\n```\\n\\nThe contract for that hook, which is worth reading before you write one:\\n\\n- It runs **exactly once per matchId**, never concurrently for the same one.\\n- It may run **more than once for the same set of players** under different\\n  matchIds, if a worker stalls and another repairs its work. **Deduplicate on\\n  `matchId`, never on the player set.**\\n- Its side effects may **survive a match that never forms** \u2014 the lease can\\n  be lost during the yield. Write it to be idempotent or cheap to abandon,\\n  and use `onAbort` to release anything expensive.\\n- If it throws, times out, or returns something unstorable, the match aborts\\n  cleanly and every player goes back in the queue.\\n\\n### Delivery\\n\\n`matched` fires on **every server holding one of the matched players**, not\\njust the one that formed the match. If none of the players are on this\\nserver, it does not fire here at all \u2014 so the handler can assume it has\\nsomeone to act on.\\n\\nA match is written to MemoryStore before it is announced, so delivery does\\nnot depend on MessagingService: typically it arrives in under 200 ms, and\\nif messaging is down entirely a poll finds it within a few seconds.","source":{"line":82,"path":"src/Matchmaker.luau"}}')}}]);